window.AUTH=window.AUTH||{};window.AUTH["22-193"]={"d":"22-193","id":"2023/22-193","n":"Muldrow v. City of St. Louis, Missouri","briefs":[{"k":"petitioner","label":"Brief of petitioner Jatonya Clayborn Muldrow","date":"2023-08-28","url":"https://www.supremecourt.gov/DocketPDF/22/22-193/278337/20230828212608509_Petitioner%20opening%20merits%20brief%20-%208.28.2023.pdf","side":"pet","n":88},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-09-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-193/278847/20230905161556485_22-193tsacUnitedStates.pdf","side":"us","n":56},{"k":"respondent","label":"Brief of respondent City of St. Louis","date":"2023-10-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-193/284695/20231011135701738_Muldrow%20Merits%20Response%20Brief.pdf","side":"res","n":55},{"k":"reply","label":"Reply of petitioner Jatonya Clayborn Muldrow","date":"2023-11-09","url":"https://www.supremecourt.gov/DocketPDF/22/22-193/289292/20231109162641399_Muldrow%20reply%20-%20final%20for%20filing%20-%2011.9.2023%20-%20e-submission.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r18_6j37.pdf","tr":true,"items":[{"t":"case","label":"Alabama v. Bozeman","cite":"533 U.S. 146","y":2001,"id":"2000/00-492","sc":1,"sum":"The Court held that the literal language of Article IV(e) of the Agreement bars any further criminal proceedings when a defendant is returned to the original place of imprisonment before trial. The Court rejected the argument that the one-day breach did not interrupt rehabilitation significantly for two reasons.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"op":2,"ar":7,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"15, 27, 28","1":"17","2":"1, 12, 19, 20, 21, 38, 48","3":"1, 2, 3, 4, 11"}},{"t":"case","label":"Brooks v. Firestone Polymers, L.L.C.","cite":"640 F. App’x 393","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/640/393/","by":{"0":"32"}},{"t":"case","label":"Brown v. Bd. of Educ. of Topeka","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"sum":"The Court decided that the \"separate but equal\" standards of racial segregation were unconstitutional, paving the way for the Civil Rights Movement and national desegregation.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Burlington Industries v. Ellerth","cite":"524 U.S. 742","y":1998,"id":"1997/97-569","sc":1,"sum":"In a 7-to-2 opinion, the Court held that employers are vicariously liable for supervisors who create hostile working conditions for those over whom they have authority.","sumSrc":"Oyez","by":{"0":"13, 34, 35, 36","1":"8, 23, 24, 25"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"op":2,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"0":"13, 20, 21, 35, 37, 38, 39, 40, 41, 50","1":"2, 8, 17, 25, 26, 30","2":"1, 12, 17-24, 32, 34-38, 40-41, 44, 47, 53","3":"3, 10, 11, 12"}},{"t":"case","label":"CBOCS W., Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Cham v. Station Operators, Inc.","cite":"685 F.3d 87","y":2012,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/685/87/","by":{"0":"42"}},{"t":"case","label":"Chambers v. District of Columbia","cite":"35 F.4th 870","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/35/870/","op":4,"ar":7,"sum":"Describing a heightened-harm requirement as “so amorphous as to accommodate inconsistent outcomes in like cases”.","sumSrc":"brief:3","by":{"0":"3, 11, 19, 26, 28, 34, 39, 40, 46, 47, 48","1":"11, 18, 20, 22, 26","2":"29, 37","3":"3, 4, 8, 14, 19, 22, 24"}},{"t":"case","label":"vii Clegg v. Ark. Dep’t of Corr.","cite":"496 F.3d 922","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/496/922/","by":{"0":"31, 42","1":"6"}},{"t":"case","label":"Cole v. Wake Cnty. Bd. of Educ.","cite":"494 F. Supp. 3d 338","y":2020,"court":"E.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/494/338/","op":1,"by":{"0":"42"}},{"t":"case","label":"Comcast Corp. v. Nat’l Ass’n of Afr. Am.Owned Media","cite":"140 S. Ct. 1009","y":2020,"id":"2019/18-1171","sc":1,"sum":"The Court held that a claim of race discrimination under 42 U.S.C. § 1981 requires that the plaintiff show that race was a but-for cause of the plaintiff's injury.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Crady v. Liberty Nat’l Bank & Tr. Co. of Ind.","cite":"993 F.2d 132","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/993/132/","by":{"0":"32","1":"16"}},{"t":"case","label":"Crawford v. Metro. Gov’t of Nashville","cite":"555 U.S. 271","y":2008,"id":"2008/06-1595","sc":1,"sum":"The Court held that the anti-retaliation provision of Title VII extends to people who participate in an internal investigation, even if they are not speaking on their own initiative.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Creggett v. Jefferson Cnty. Bd. of Educ.","cite":"491 F. App’x 561","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/491/561/","by":{"0":"42"}},{"t":"case","label":"Davis v. KARK-TV, Inc.","cite":"421 F.3d 699","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/421/699/","by":{"0":"44"}},{"t":"case","label":"Davis v. Legal Servs. Ala., Inc.","cite":"19 F.4th 1261","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/1261/","ar":1,"by":{"0":"43"}},{"t":"case","label":"Dir., Off. of Workers’ Comp. Programs, Dep’t of Lab. v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Douglas v. Donovan","cite":"559 F.3d 549","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/559/549/","by":{"0":"43"}},{"t":"case","label":"viii Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"44","2":"30, 31"}},{"t":"case","label":"Env’t Def. Fund, Inc. v. E.P.A.","cite":"82 F.3d 451","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/82/451/","by":{"0":"49"}},{"t":"case","label":"Faragher v. City of Boca Raton","cite":"524 U.S. 775","y":1998,"id":"1997/97-282","sc":1,"sum":"The Court held that an employer is vicariously liable under Title VII of the Civil Rights Act of 1964 for actionable discrimination caused by a supervisor.","sumSrc":"Oyez","by":{"0":"50","2":"21, 22, 24","3":"9"}},{"t":"case","label":"Fenney v. Dakota, Minn. & E. R.R. Co.","cite":"327 F.3d 707","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/327/707/","by":{"0":"43"}},{"t":"case","label":"Ford Motor Co. v. N.L.R.B.","cite":"441 U.S. 488","y":1979,"id":"1978/77-1806","sc":1,"sum":"In-plant cafeteria and vending machine food and beverage prices and services are \"terms and conditions of employment\" subject to mandatory collective bargaining under §§ 8 (a) (5) and 8 (d) of the NLRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Franks v. Bowman Transp. Co.","cite":"424 U.S. 747","y":1976,"id":"1975/74-728","sc":1,"sum":"In a class action against respondent employer and certain labor unions (of which respondent union is the successor) petitioners alleged various racially discriminatory employment practices in violation of Title VII of the Civil Rights Act of 1964 (Act), especially with respect to employment of over-the-road (OTR) truck drivers. After certifying the action as a class action and, inter alia, designating one of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"27"}},{"t":"case","label":"Groff v. DeJoy","cite":"143 S. Ct. 2279","y":2023,"id":"2022/22-174","sc":1,"ar":1,"sum":"Title VII requires an employer that denies a religious accommodation to show that the burden of granting an accommodation would result in substantial increased costs in relation to the conduct of its particular business.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15, 17, 46","1":"22"}},{"t":"case","label":"Hamilton v. Dallas Cnty.","cite":"2023 WL 5316716","y":2023,"court":"5th Cir. Aug. 18","by":{"0":"39, 42, 43, 44, 47","1":"11"}},{"t":"case","label":"Harlston v. McDonnell Douglas","cite":"37 F.3d 379","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/37/379/","by":{"0":"32-33, 42","1":"16"}},{"t":"case","label":"Harris v. Forklift Sys., Inc.","cite":"510 U.S 17","y":1993,"url":"https://www.courtlistener.com/c/U.S/510/17/","by":{"0":"34"}},{"t":"case","label":"Hase v. Mo. Div. of Emp. Sec.","cite":"972 F.2d 893","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/972/893/","by":{"0":"32"}},{"t":"case","label":"ix Heckler v. Mathews","cite":"465 U.S. 728","y":1984,"id":"1983/82-1050","sc":1,"ar":3,"sum":"The unanimous Court upheld the law. Justice Brennan granted that the 1977 amendments temporarily revived gender-based eligibility requirements, but maintained that they served a legitimate government interest, namely, they protected individuals who had planned for their retirements relying on the law as it stood before the Court's Califano decision.","sumSrc":"Oyez","by":{"0":"48","1":"18"}},{"t":"case","label":"Higgins v. Gonzales","cite":"481 F.3d 578","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/481/578/","by":{"0":"41"}},{"t":"case","label":"Hishon v. King & Spalding","cite":"467 U.S. 69","y":1984,"id":"1983/82-940","sc":1,"sum":"The Court held that Title VII makes it illegal for an employer to discriminate against any employee on the basis of their sex. In this case, the Court held that the promise of equal consideration for partnership that went along with Hishon’s employment was contractual in nature and subject to the regulations of Title VII.","sumSrc":"Oyez","by":{"0":"18, 21","1":"12, 23"}},{"t":"case","label":"Int’l Bhd. of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","1":"28","3":"5"}},{"t":"case","label":"Jackman v. Fifth Jud. Dist. Dep’t of Corr. Servs.","cite":"728 F.3d 800","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/728/800/","by":{"0":"10, 26, 28"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Lavender v. Kurn","cite":"327 U.S. 645","y":1946,"id":"scdb/1945-082","sc":1,"sum":"1. In this action under the Federal Employers' Liability Act, the evidence of the defendants' negligence (detailed in the opinion) was sufficient to justify submission of the case to the jury; and the judgment of the appellate court setting aside the verdict for the plaintiff can not be sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Ledergerber v. Stangler","cite":"122 F.3d 1142","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/1142/","by":{"0":"26, 41"}},{"t":"case","label":"Loc. Union No. 189, Amalgamated Meat Cutters & Butcher Workmen of N. Am. v. Jewel Tea Co.","cite":"381 U.S. 676","y":1965,"id":"1964/240","sc":1,"sum":"The judgment is reversed. Pp. 679-735. 331 F. 2d 547, reversed. MR. JUSTICE WHITE, joined by THE CHIEF JUSTICE and MR. JUSTICE BRENNAN, concluded, that:.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20-21"}},{"t":"case","label":"McDonnell Douglas Corp. v. Green","cite":"411 U.S. 792","y":1973,"id":"1972/72-490","sc":1,"sum":"The Court held that the findings of the EEOC could not bar a suit that meets the jurisdictional requirements for suing in federal district court. The Court also held that Congress meant to prevent discriminatory hiring practices, not guarantee jobs, so that the complainant in an employment discrimination lawsuit carries the initial burden to present a prima facie case for racial discrimination.","sumSrc":"Oyez","by":{"0":"3, 12, 21, 27, 31, 32","1":"2, 15, 17, 23, 27","2":"49","3":"6, 14"}},{"t":"case","label":"Meritor Savings Bank, FSB v. Vinson","cite":"477 U.S. 57","y":1986,"id":"1985/84-1979","sc":1,"op":1,"ar":2,"sum":"The Court held that the language of Title VII was \"not limited to 'economic' or 'tangible' discrimination,\" finding that Congress intended \"'to strike at the entire spectrum of disparate treatment of men and women' in employment. . .\" The Court noted that guidelines issued by the EEOC specified that sexual harassment leading to noneconomic injury was a form of sex discrimination prohibited by Title VII.","sumSrc":"Oyez","by":{"0":"19, 33, 34, 35, 41","1":"10, 12, 13, 17, 22, 23, 29","2":"21, 41, 49","3":"8, 9, 10"}},{"t":"case","label":"x Morales-Vallellanes v. Potter","cite":"605 F.3d 27","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/605/27/","by":{"0":"36"}},{"t":"case","label":"N.L.R.B. v. Almet, Inc.","cite":"987 F.2d 445","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/987/445/","by":{"0":"20"}},{"t":"case","label":"N.L.R.B. v. Buddy Schoellkopf Prods., Inc.","cite":"410 F.2d 82","y":1969,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/410/82/","by":{"0":"20"}},{"t":"case","label":"N.L.R.B. v. Great Dane Trailers, Inc.","cite":"388 U.S. 26","y":1967,"id":"1966/781","sc":1,"sum":"Respondent company and a union representing its employees entered into a collective bargaining agreement which contained a provision for employee vacation benefits, to be paid on the Friday nearest July 1 of each year. Most of the employees went on strike May 16, 1963, and many were gradually replaced by respondent. A demand for vacation pay by the strikers on July 12, 1963, was rejected by the company on the ground …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"N.L.R.B. v. Moore Bus. Forms, Inc.","cite":"574 F.2d 835","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/574/835/","by":{"0":"20"}},{"t":"case","label":"Nat’l Credit Union Admin. v. First Nat’l Bank & Trust Co.","cite":"522 U.S. 479","y":1998,"id":"1997/96-843","sc":1,"sum":"The Court held that banks and professional associations have prudential standing under the APA to seek federal-court review of the NCUA's interpretation of section 109.","sumSrc":"Oyez","by":{"0":"30","2":"28"}},{"t":"case","label":"O’Keeffe v. Smith, Hinchman & Grylls Assocs., Inc.","cite":"380 U.S. 359","y":1965,"id":"1964/307","sc":1,"sum":"Since the Act provides that the Deputy Commissioner's order may be set aside by a reviewing court only if not in accordance with law and since the Deputy Commissioner correctly applied the standard of O'Leary v. Brown-Pacific-Maxon, Inc., 340 U. S. 504, that the conditions of employment create the \"zone of special danger\" out of which the injury arose, his holding cannot be said to be irrational or without …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Olmstead v. L.C. ex rel. Zimring","cite":"527 U.S. 581","y":1999,"id":"1998/98-536","sc":1,"sum":"The Court then found that the ADA required the placement of patients with mental disabilities in \"integrated settings\" when they are medically cleared for such settings, they themselves express a desire for such settings, and the resources for such a transfer are available.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"op":3,"ar":5,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"0":"3, 19","1":"12, 29","2":"12, 17, 18, 20, 22, 23, 32, 35, 36, 49, 53","3":"8, 9"}},{"t":"case","label":"Ortiz-Diaz v. U.S. Dep’t of Hous. & Urb. Dev.","cite":"867 F.3d 70","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/867/70/","by":{"0":"11, 16","1":"14"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"xi Peterson v. Linear Controls, Inc.","cite":"757 F. App’x 370","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/757/370/","by":{"0":"42"}},{"t":"case","label":"Piercy v. Maketa","cite":"480 F.3d 1192","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/480/1192/","by":{"0":"43"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Public Citizen v. Young","cite":"831 F.2d 1108","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/831/1108/","by":{"0":"49"}},{"t":"case","label":"Reeves v. Sanderson Plumbing Prods., Inc.","cite":"530 U.S. 133","y":2000,"id":"1999/99-536","sc":1,"sum":"The Court held that \"[a] plaintiff's prima facie case of discrimination, combined with sufficient evidence for a reasonable factfinder to reject the employer's nondiscriminatory explanation for its decision, may be adequate to sustain a finding of liability for intentional discrimination under the ADEA.\" The ruling means that an employer is liable to a former employee under the Age Discrimination in Employment Act of 1967 if a reasonable jury can find that the employer's explanation for the employee's dismissal was pretext for discrimination.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"0":"21, 41"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Spring v. Sheboygan Area Sch. Dist.","cite":"865 F.2d 8836","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/865/8836/","by":{"0":"42"}},{"t":"case","label":"Stewart v. Union Cnty. Bd. of Educ.","cite":"655 F. App’x 151","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/655/151/","by":{"0":"42"}},{"t":"case","label":"xii Students for Fair Admissions, Inc. v. President & Fellows of Harvard Coll.","cite":"143 S. Ct. 2141","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/2141/","sc":1,"by":{"0":"41, 48, 49"}},{"t":"case","label":"Tex. Dep’t of Cmty. Affairs v. Burdine","cite":"450 U.S. 248","y":1981,"id":"1980/79-1764","sc":1,"sum":"A case that held that the defendant bears the burden of proof to provide nondiscriminatory reasons for termination after a former employee has proven a prima facie case that the termination violated the Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"50","2":"32"}},{"t":"case","label":"Tex. Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"0":"31","1":"21"}},{"t":"case","label":"Thompson v. N. Am. Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Threat v. City of Cleveland","cite":"6 F.4th 672","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/672/","ar":2,"by":{"0":"15, 33, 43, 44, 47","1":"11","2":"32","3":"7, 19"}},{"t":"case","label":"Trans World Airlines, Inc. v. Hardison","cite":"432 U.S. 63","y":1977,"id":"1976/75-1126","sc":1,"sum":"Respondent Hardison (hereafter respondent) was employed by Trans World Airlines (TWA), petitioner in No. 75-1126, in a department that operated 24 hours a day throughout the year in connection with an airplane maintenance and overhaul base. Respondent was subject to a seniority system in a collective-bargaining agreement between TWA and the International Association of Machinists & Aerospace Workers (union), …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"U.S. Postal Serv. Bd. of Governors v. Aikens","cite":"460 U.S. 711","y":1983,"id":"1982/81-1044","sc":1,"sum":"By framing the issue here in terms of whether a prima facie case is established by an employee's showing only that he was black, that he applied for a promotion for which he possessed the minimum qualifications, and that the employer selected a nonminority applicant, the parties and the Court of Appeals have unnecessarily evaded the ultimate question of discrimination vel non. By establishing a prima facie case, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"United States v. Burke","cite":"504 U.S. 229","y":1992,"id":"1991/91-42","sc":1,"sum":"Backpay awards in settlement of Title VII claims are not excludable from gross income under §104(a)(2).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Vance v. Ball State Univ.","cite":"570 U.S. 421","y":2013,"id":"2012/11-556","sc":1,"sum":"The Court held that, for purposes of liability for workplace harassment, the definition of \"supervisor\" is limited to a person empowered to take tangible employment action against the victim.","sumSrc":"Oyez","by":{"0":"37","2":"43"}},{"t":"case","label":"Wedow v. City of Kansas City","cite":"442 F.3d 661","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/442/661/","by":{"0":"10"}},{"t":"case","label":"Wis. Dep’t of Revenue v. William Wrigley, Jr., Co.","cite":"505 U.S. 214","y":1992,"id":"1991/91-119","sc":1,"sum":"Respondent's activities in Wisconsin fell outside the protection of §381(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","1":"21, 22","2":"32"}},{"t":"case","label":"xiii Zhuang v. Datacard Corp.","cite":"414 F.3d 849","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/414/849/","by":{"0":"42"}},{"t":"usc","label":"8 U.S.C. § 1324b","url":"https://www.law.cornell.edu/uscode/text/8/1324b","stext":{"head":"§1324b. Unfair immigration-related employment practices","paras":[[0,"(a) Prohibition of discrimination based on national origin or citizenship status"],[0,"(1) General rule"],[1,"It is an unfair immigration-related employment practice for a person or other entity to discriminate against any individual (other than an unauthorized alien, as defined in section 1324a(h)(3) of this title) with respect to the hiring, or recruitment or referral for a fee, of the individual for employment or the discharging of the individual from employment—"],[2,"(A) because of such individual's national origin, or"],[2,"(B) in the case of a protected individual (as defined in paragraph (3)), because of such individual's citizenship status."],[0,"(2) Exceptions"],[1,"Paragraph (1) shall not apply to—"],[2,"(A) a person or other entity that employs three or fewer employees,"],[2,"(B) a person's or entity's discrimination because of an individual's national origin if the discrimination with respect to that person or entity and that individual is covered under section 703 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–2], or"],[2,"(C) discrimination because of citizenship status which is otherwise required in order to comply with law, regulation, or executive order, or required by Federal, State, or local government contract, or which the Attorney General determines to be essential for an employer to do business with an agency or department of the Federal, State, or local government."],[0,"(3) \"Protected individual\" defined"],[1,"As used in paragraph (1), the term \"protected individual\" means an individual who—"],[2,"(A) is a citizen or national of the United States, or"],[2,"(B) is an alien who is lawfully admitted for permanent residence, is granted the status of an alien lawfully admitted for temporary residence under section 1160(a) or 1255a(a)(1) of this title, is admitted as a refugee under section 1157 of this title, or is granted asylum under section 1158 of this title; but does not include (i) an alien who fails to apply for naturalization within six months of the date the alien first becomes eligible (by virtue of period of lawful permanent residence) to apply for naturalization or, if later, within six months after November 6, 1986, and (ii) an alien who has applied on a timely basis, but has not been naturalized as a citizen within 2 years after the date of the application, unless the alien can establish that the alien is actively pursuing naturalization, except that time consumed in the Service's processing the application shall not be counted toward the 2-year period."],[0,"(4) Additional exception providing right to prefer equally qualified citizens"],[1,"Notwithstanding any other provision of this section, it is not an unfair immigration-related employment practice for a person or other entity to prefer to hire, recruit, or refer an individual who is a citizen or national of the United States over another individual who is an alien if the two individuals are equally qualified."],[0,"(5) Prohibition of intimidation or retaliation"],[1,"It is also an unfair immigration-related employment practice for a person or other entity to intimidate, threaten, coerce, or retaliate against any individual for the purpose of interfering with any right or privilege secured under this section or because the individual intends to file or has filed a charge or a complaint, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under this section. An individual so intimidated, threatened, coerced, or retaliated against shall be considered, for purposes of subsections (d) and (g), to have been discriminated against."],[0,"(6) Treatment of certain documentary practices as employment practices"],[1,"A person's or other entity's request, for purposes of satisfying the requirements of section 1324a(b) of this title, for more or different documents than are required under such section or refusing to honor documents tendered that on their face reasonably appear to be genuine shall be treated as an unfair immigration-related employment practice if made for the purpose or with the intent of discriminating against an individual in violation of paragraph (1)."],[0,"(b) Charges of violations"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), any person alleging that the person is adversely affected directly by an unfair immigration-related employment practice (or a person on that person's behalf) or an officer of the Service alleging that an unfair immigration-related employment practice has occurred or is occurring may file a charge respecting such practice or violation with the Special Counsel (appointed under subsection (c)). Charges shall be in writing under oath or affirmation and shall contain such information as the Attorney General requires. The Special Counsel by certified mail shall serve a notice of the charge (including the date, place, and circumstances of the alleged unfair immigration-related employment practice) on the person or entity involved within 10 days."],[0,"(2) No overlap with EEOC complaints"],[1,"No charge may be filed respecting an unfair immigration-related employment practice described in subsection (a)(1)(A) if a charge with respect to that practice based on the same set of facts has been filed with the Equal Employment Opportunity Commission under title VII of the Civil Rights Act of 1964 [42 U.S.C. 2000e et seq.], unless the charge is dismissed as being outside the scope of such title. No charge respecting an employment practice may be filed with the Equal Employment Opportunity Commission under such title if a charge with respect to such practice based on the same set of facts has been filed under this subsection, unless the charge is dismissed under this section as being outside the scope of this section."],[0,"(c) Special Counsel"],[0,"(1) Appointment"],[1,"The President shall appoint, by and with the advice and consent of the Senate, a Special Counsel for Immigration-Related Unfair Employment Practices (hereinafter in this section referred to as the \"Special Counsel\") within the Department of Justice to serve for a term of four years. In the case of a vacancy in the office of the Special Counsel the President may designate the officer or employee who shall act as Special Counsel during such vacancy."],[0,"(2) Duties"],[1,"The Special Counsel shall be responsible for investigation of charges and issuance of complaints under this section and in respect of the prosecution of all such complaints before administrative law judges and the exercise of certain functions under subsection (j)(1)."],[0,"(3) Compensation"],[1,"The Special Counsel is entitled to receive compensation at a rate not to exceed the rate now or hereafter provided for grade GS–17 of the General Schedule, under section 5332 of title 5."],[0,"(4) Regional offices"],[1,"The Special Counsel, in accordance with regulations of the Attorney General, shall establish such regional offices as may be necessary to carry out his duties."],[0,"(d) Investigation of charges"],[0,"(1) By Special Counsel"],[1,"The Special Counsel shall investigate each charge received and, within 120 days of the date of the receipt of the charge, determine whether or not there is reasonable cause to believe that the charge is true and whether or not to bring a complaint with respect to the charge before an administrative law judge. The Special Counsel may, on his own initiative, conduct investigations respecting unfair immigration-related employment practices and, based on such an investigation and subject to paragraph (3), file a complaint before such a judge."],[0,"(2) Private actions"],[1,"If the Special Counsel, after receiving such a charge respecting an unfair immigration-related employment practice which alleges knowing and intentional discriminatory activity or a pattern or practice of discriminatory activity, has not filed a complaint before an administrative law judge with respect to such charge within such 120-day period, the Special Counsel shall notify the person making the charge of the determination not to file such a complaint during such period and the person making the charge may (subject to paragraph (3)) file a complaint directly before such a judge within 90 days after the date of receipt of the notice. The Special Counsel's failure to file such a complaint within such 120-day period shall not affect the right of the Special Counsel to investigate the charge or to bring a complaint before an administrative law judge during such 90-day period."],[0,"(3) Time limitations on complaints"],[1,"No complaint may be filed respecting any unfair immigration-related employment practice occurring more than 180 days prior to the date of the filing of the charge with the Special Counsel. This subparagraph shall not prevent the subsequent amending of a charge or complaint under subsection (e)(1)."],[0,"(e) Hearings"],[0,"(1) Notice"],[1,"Whenever a complaint is made that a person or entity has engaged in or is engaging in any such unfair immigration-related employment practice, an administrative law judge shall have power to issue and cause to be served upon such person or entity a copy of the complaint and a notice of hearing before the judge at a place therein fixed, not less than five days after the serving of the complaint. Any such complaint may be amended by the judge conducting the hearing, upon the motion of the party filing the complaint, in the judge's discretion at any time prior to the issuance of an order based thereon. The person or entity so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1324b?type=usc&year=mostrecent&link-type=html"},"head":"§1324b. Unfair immigration-related employment practices","tname":"Aliens and Nationality","by":{"0":"44","2":"45"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(a)(3)","(d)"],"stext":{"head":"§158. Unfair labor practices","paras":[[0,"(a) Unfair labor practices by employer"],[0,"It shall be an unfair labor practice for an employer—"],[1,"(1) to interfere with, restrain, or coerce employees in the exercise of the rights guaranteed in section 157 of this title;"],[1,"(2) to dominate or interfere with the formation or administration of any labor organization or contribute financial or other support to it: Provided, That subject to rules and regulations made and published by the Board pursuant to section 156 of this title, an employer shall not be prohibited from permitting employees to confer with him during working hours without loss of time or pay;"],[1,"(3) by discrimination in regard to hire or tenure of employment or any term or condition of employment to encourage or discourage membership in any labor organization: Provided, That nothing in this subchapter, or in any other statute of the United States, shall preclude an employer from making an agreement with a labor organization (not established, maintained, or assisted by any action defined in this subsection as an unfair labor practice) to require as a condition of employment membership therein on or after the thirtieth day following the beginning of such employment or the effective date of such agreement, whichever is the later, (i) if such labor organization is the representative of the employees as provided in section 159(a) of this title, in the appropriate collective-bargaining unit covered by such agreement when made, and (ii) unless following an election held as provided in section 159(e) of this title within one year preceding the effective date of such agreement, the Board shall have certified that at least a majority of the employees eligible to vote in such election have voted to rescind the authority of such labor organization to make such an agreement: Provided further, That no employer shall justify any discrimination against an employee for nonmembership in a labor organization (A) if he has reasonable grounds for believing that such membership was not available to the employee on the same terms and conditions generally applicable to other members, or (B) if he has reasonable grounds for believing that membership was denied or terminated for reasons other than the failure of the employee to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(4) to discharge or otherwise discriminate against an employee because he has filed charges or given testimony under this subchapter;"],[1,"(5) to refuse to bargain collectively with the representatives of his employees, subject to the provisions of section 159(a) of this title."],[0,"(b) Unfair labor practices by labor organization"],[0,"It shall be an unfair labor practice for a labor organization or its agents—"],[1,"(1) to restrain or coerce (A) employees in the exercise of the rights guaranteed in section 157 of this title: Provided, That this paragraph shall not impair the right of a labor organization to prescribe its own rules with respect to the acquisition or retention of membership therein; or (B) an employer in the selection of his representatives for the purposes of collective bargaining or the adjustment of grievances;"],[1,"(2) to cause or attempt to cause an employer to discriminate against an employee in violation of subsection (a)(3) or to discriminate against an employee with respect to whom membership in such organization has been denied or terminated on some ground other than his failure to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(3) to refuse to bargain collectively with an employer, provided it is the representative of his employees subject to the provisions of section 159(a) of this title;"],[1,"(4)(i) to engage in, or to induce or encourage any individual employed by any person engaged in commerce or in an industry affecting commerce to engage in, a strike or a refusal in the course of his employment to use, manufacture, process, transport, or otherwise handle or work on any goods, articles, materials, or commodities or to perform any services; or (ii) to threaten, coerce, or restrain any person engaged in commerce or in an industry affecting commerce, where in either case an object thereof is—"],[2,"(A) forcing or requiring any employer or self-employed person to join any labor or employer organization or to enter into any agreement which is prohibited by subsection (e);"],[2,"(B) forcing or requiring any person to cease using, selling, handling, transporting, or otherwise dealing in the products of any other producer, processor, or manufacturer, or to cease doing business with any other person, or forcing or requiring any other employer to recognize or bargain with a labor organization as the representative of his employees unless such labor organization has been certified as the representative of such employees under the provisions of section 159 of this title: Provided, That nothing contained in this clause (B) shall be construed to make unlawful, where not otherwise unlawful, any primary strike or primary picketing;"],[2,"(C) forcing or requiring any employer to recognize or bargain with a particular labor organization as the representative of his employees if another labor organization has been certified as the representative of such employees under the provisions of section 159 of this title;"],[2,"(D) forcing or requiring any employer to assign particular work to employees in a particular labor organization or in a particular trade, craft, or class rather than to employees in another labor organization or in another trade, craft, or class, unless such employer is failing to conform to an order or certification of the Board determining the bargaining representative for employees performing such work:"],[1,"Provided, That nothing contained in this subsection shall be construed to make unlawful a refusal by any person to enter upon the premises of any employer (other than his own employer), if the employees of such employer are engaged in a strike ratified or approved by a representative of such employees whom such employer is required to recognize under this subchapter: Provided further, That for the purposes of this paragraph (4) only, nothing contained in such paragraph shall be construed to prohibit publicity, other than picketing, for the purpose of truthfully advising the public, including consumers and members of a labor organization, that a product or products are produced by an employer with whom the labor organization has a primary dispute and are distributed by another employer, as long as such publicity does not have an effect of inducing any individual employed by any person other than the primary employer in the course of his employment to refuse to pick up, deliver, or transport any goods, or not to perform any services, at the establishment of the employer engaged in such distribution;"],[1,"(5) to require of employees covered by an agreement authorized under subsection (a)(3) the payment, as a condition precedent to becoming a member of such organization, of a fee in an amount which the Board finds excessive or discriminatory under all the circumstances. In making such a finding, the Board shall consider, among other relevant factors, the practices and customs of labor organizations in the particular industry, and the wages currently paid to the employees affected;"],[1,"(6) to cause or attempt to cause an employer to pay or deliver or agree to pay or deliver any money or other thing of value, in the nature of an exaction, for services which are not performed or not to be performed; and"],[1,"(7) to picket or cause to be picketed, or threaten to picket or cause to be picketed, any employer where an object thereof is forcing or requiring an employer to recognize or bargain with a labor organization as the representative of his employees, or forcing or requiring the employees of an employer to accept or select such labor organization as their collective bargaining representative, unless such labor organization is currently certified as the representative of such employees:"],[2,"(A) where the employer has lawfully recognized in accordance with this subchapter any other labor organization and a question concerning representation may not appropriately be raised under section 159(c) of this title,"],[2,"(B) where within the preceding twelve months a valid election under section 159(c) of this title has been conducted, or"],[2,"(C) where such picketing has been conducted without a petition under section 159(c) of this title being filed within a reasonable period of time not to exceed thirty days from the commencement of such picketing: Provided, That when such a petition has been filed the Board shall forthwith, without regard to the provisions of section 159(c)(1) of this title or the absence of a showing of a substantial interest on the part of the labor organization, direct an election in such unit as the Board finds to be appropriate and shall certify the results thereof: Provided further, That nothing in this subparagraph (C) shall be construed to prohibit any picketing or other publicity for the purpose of truthfully advising the public (including consumers) that an employer does not employ members of, or have a contract with, a labor organization, unless an effect of such picketing is to induce any individual employed by any other person in the course of his employment, not to pick up, deliver or transport any goods or not to perform any services."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/158?type=usc&year=mostrecent&link-type=html"},"head":"§158. Unfair labor practices","tname":"Labor","by":{"0":"20, 20","1":"12, 12"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)(1)"],"by":{"0":"44"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","subs":["(b)"],"stext":{"head":"§1981. Equal rights under the law","paras":[[0,"(a) Statement of equal rights"],[0,"All persons within the jurisdiction of the United States shall have the same right in every State and Territory to make and enforce contracts, to sue, be parties, give evidence, and to the full and equal benefit of all laws and proceedings for the security of persons and property as is enjoyed by white citizens, and shall be subject to like punishment, pains, penalties, taxes, licenses, and exactions of every kind, and to no other."],[0,"(b) \"Make and enforce contracts\" defined"],[0,"For purposes of this section, the term \"make and enforce contracts\" includes the making, performance, modification, and termination of contracts, and the enjoyment of all benefits, privileges, terms, and conditions of the contractual relationship."],[0,"(c) Protection against impairment"],[0,"The rights protected by this section are protected against impairment by nongovernmental discrimination and impairment under color of State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981?type=usc&year=mostrecent&link-type=html"},"head":"§1981. Equal rights under the law","tname":"The Public Health and Welfare","by":{"0":"23, 38, 24","2":"42"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(b)(3)","(b)(3)(A)"],"by":{"0":"45, 51"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)(1)","(a)(2)","(e)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"1, 2, 9, 11, 14-15, 16, 20, 24, 32, 44, 50, 31","1":"27, 27, 27","2":"1-3, 7, 12-14, 16-25, 27-31, 34-41, 43-45, 49, 13, 27, 28, 29, 30, 31","3":"1, 4, 8, 12, 13, 14, 16, 15, 16"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"stext":{"head":"§2000e–3. Other unlawful employment practices","paras":[[0,"(a) Discrimination for making charges, testifying, assisting, or participating in enforcement proceedings"],[0,"It shall be an unlawful employment practice for an employer to discriminate against any of his employees or applicants for employment, for an employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because he has opposed any practice made an unlawful employment practice by this subchapter, or because he has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under this subchapter."],[0,"(b) Printing or publication of notices or advertisements indicating prohibited preference, limitation, specification, or discrimination; occupational qualification exception"],[0,"It shall be an unlawful employment practice for an employer, labor organization, employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to print or publish or cause to be printed or published any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, or relating to admission to, or employment in, any program established to provide apprenticeship or other training by such a joint labor-management committee, indicating any preference, limitation, specification, or discrimination, based on race, color, religion, sex, or national origin, except that such a notice or advertisement may indicate a preference, limitation, specification, or discrimination based on religion, sex, or national origin when religion, sex, or national origin is a bona fide occupational qualification for employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-3?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–3. Other unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"37","1":"3","2":"18-19, 21-24, 28, 37, 44"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(e)(1)","(f)(1)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"0":"51, 30, 51","1":"3","3":"2"}},{"t":"reg","label":"29 C.F.R. § 1614.105","url":"https://www.ecfr.gov/current/title-29/section-1614.105","subs":["(a)(1)"],"by":{"0":"51"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"10"}},{"t":"case","label":"Bell Atlantic Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Bonenberger v. St. Louis Metro. Police Dept","cite":"810 F.3d 1103","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1103/","by":{"1":"28, 29"}},{"t":"case","label":"Brown v. Mayorkas","cite":"2023 WL 330862","y":2023,"court":"D.D.C. May, 8","by":{"1":"31"}},{"t":"case","label":"Dorsch v. L.B. Foster Co.","cite":"782 F.2d 1421","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/1421/","by":{"1":"15"}},{"t":"case","label":"EEOC v. AutoZone, Inc.","cite":"860 F.3d 564","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/860/564/","sum":"Holding that employee’s allegedly race-based transfer to keep a particular store “ ‘predominantly Hispanic’ ” was not an adverse-employment action under Section 2000e-2(a)(2) and indicating it likewise would not qualify under Section 2000e-2(a)(1).","sumSrc":"brief:1","by":{"1":"27","3":"7"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"op":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"1":"30","3":"15"}},{"t":"case","label":"Garza v. Blinken","cite":"2023 WL 2239352","y":2023,"court":"D.D.C. Feb. 27","by":{"1":"31"}},{"t":"case","label":"Harris v. Forklift Sys., Inc.","cite":"510 U.S. 17","y":1993,"id":"1993/92-1168","sc":1,"sum":"The Court found that the district court had been wrong to focus on whether or not the harassment had caused \"concrete psychological harm.\" Instead, Justice O'Connor wrote that the court should have focused on whether the conduct was hostile or abusive. \"Certainly Title VII bars conduct that would seriously affect a reasonable person's psychological well being, but the statute is not limited to such conduct.","sumSrc":"Oyez","by":{"1":"12, 23, 30","2":"40","3":"8, 9"}},{"t":"case","label":"Heavans v. Dodaro","cite":"2022 WL 17904237","y":2022,"court":"D.D.C. Dec. 23","by":{"1":"31"}},{"t":"case","label":"Herrnreiter v. Chicago Hous. Auth.","cite":"315 F.3d 742","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/315/742/","sum":"Holding that a plaintiff in a Title VII race-discrimination case must show a “materially adverse employment action” and that the plaintiff’s lateral transfer did not qualify.","sumSrc":"brief:1","by":{"1":"16"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Keene Corp. v. United States","cite":"508 U.S. 200","y":1993,"id":"1992/92-166","sc":1,"sum":"Petitioner Keene Corporation has been sued by thousands of plaintiffs alleging injury from exposure to asbestos fibers and dust released from Keene products. Claiming that it was following Government specifications in including asbestos within products supplied to Government projects, and that it actually bought asbestos fiber from the Government, Keene filed two complaints against the United States in the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","3":"16"}},{"t":"case","label":"Kocsis v. Multi-Care Mgmt., Inc.","cite":"97 F.3d 876","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/97/876/","by":{"1":"16"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"1":"20","3":"17"}},{"t":"case","label":"NLRB v. Local 138, Int’l Union of Operating Eng’rs, AFL-CIO","cite":"293 F.2d 187","y":1961,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/293/187/","by":{"1":"13"}},{"t":"case","label":"NLRB v. Southeastern Pipe Line Co.","cite":"210 F.2d 643","y":1954,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/210/643/","by":{"1":"13"}},{"t":"case","label":"Rester v. Stephens Media, LLC","cite":"739 F.3d 1127","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/1127/","by":{"1":"5"}},{"t":"case","label":"Sanchez v. Denver Pub. Schs.","cite":"164 F.3d 527","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/164/527/","op":1,"by":{"1":"16"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"21","3":"15"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"Young v. Will Cnty. Dep’t of Public Aid","cite":"882 F.2d 290","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/882/290/","by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)(1)","(a)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"1":"1-3, 5-20, 22, 24-28, 30-32","2":"45, 25","3":"14"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(a)","(b)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"1":"1-3, 5-20, 22, 24-28, 30-32","2":"31, 31"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(a)"],"by":{"1":"3, 12"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","by":{"1":"12"}},{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Anderson v. Liberty Lobby, Inc.","cite":"477 U.S. 242","y":1986,"id":"1985/84-1602","sc":1,"sum":"In a 6-to-3 opinion, the Court held that the purpose of summary judgments is to determine if the evidence is so one-sided that a party should prevail as a matter of law. Summary judgments will not lie if there is a sufficient likelihood that a reasonable jury would return a verdict favorable to the nonmoving party.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"2":"25, 26, 27","3":"14"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"32"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Consumer Prod. Safety Comm’n v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"sum":"The Court held that the term \"cocaine base\" encompasses every form of cocaine that is classified chemically as a base.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"sum":"The language \"any money or other property of the United States\" in § 2114 includes the $1,800 belonging to the United States and entrusted to the Secret Service agent as \"flash money,\" and thus by using a pistol in an effort to rob the agent petitioners fell squarely within the prohibitions of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Harris v. Bell","cite":"254 U.S. 103","y":1920,"id":"scdb/1920-034","sc":1,"sum":"1. Lands representing the distributive share of a Creek Indian who died after his enrollment and before their selection or allotment and which thereafter were selected, allotted and deeded in his name, pursuant to the'Act of April 26, 1906, c. 1876, § 5, 34 Stat. 137, and earlier statutes, are to be considered as going to hiá heirs, not as a direct allotment to them but as an inheritance, the alienability of which …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Kalamazoo Cnty. Rd. Comm’n v. Deleon","cite":"135 S. Ct. 783","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/783/","sc":1,"sum":"Noting that, “since respondent cannot satisfy the antiretaliation standard, it follows a fortiori that he cannot satisfy the discrimination standard,” as “Title VII’s antiretaliation … standard is broader than the ordinary discrimination standard”.","sumSrc":"brief:2","by":{"2":"36"}},{"t":"case","label":"Lockhart v. United States","cite":"577 U.S. 347","y":2016,"id":"2015/14-8358","sc":1,"sum":"The Court determined that a prior conviction of “aggravated sexual abuse” or “sexual abuse” may trigger a mandatory minimum sentence, even when the prior conviction did not involve a minor.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"42"}},{"t":"case","label":"Pa. State Police v. Suders","cite":"542 U.S. 129","y":2004,"id":"2003/03-95","sc":1,"sum":"In an 8-to-1 decision written by Justice Ruth Bader Ginsburg, the Court ruled that an employee faced with a situation in which a \"reasonable person ... would have felt compelled to resign\" could bring suit even if she had not filed a report with the employer before resigning.","sumSrc":"Oyez","by":{"2":"18, 22"}},{"t":"case","label":"Powerex v. Reliant Energy Servs. Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Stafford v. Briggs","cite":"444 U.S. 527","y":1980,"id":"1978/77-1546","sc":1,"sum":"The Supreme Court held that the language of the statute clearly indicated that Congress meant to restrict the applicability of the statute to employees currently employed by the government at the time of filing. Additionally, the legislative history of the statute shows Congress’ desire to restrict civil actions against governmental officials to those acting in their official capacity.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Students for Fair Admissions, Inc. v. President & Fellows of Harvard Coll.","cite":"600 U.S. 181","y":2023,"id":"2022/20-1199","sc":1,"sum":"The admissions programs at Harvard College and the University of North Carolina violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Sullivan v. Stroop","cite":"496 U.S. 478","y":1990,"id":"1989/89-535","sc":1,"sum":"Title II \"child's insurance benefits\" do not constitute \"child support\" within the meaning of § 602(a)(8)(A)(vi). The clear and unambiguous language of the statute demonstrates thau Congress used \"child support\" throughout Title IV as a term of art referring exclusively to payments from absent parents. See, e. g., § 651, the first provision in Part D of Title IV, which is devoted exclusively to \"Child Support and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"2":"30, 31"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"United States v. Price","cite":"361 U.S. 304","y":1960,"id":"1959/48","sc":1,"sum":"Under § 272 (a) (1) of the Internal Revenue Code of 1939, as amended, failure of the Commissioner of Internal Revenue to send to a taxpayer a 90-day notice of a deficiency in his income tax return does not bar an action by the United States to collect such deficiency and statutory interest thereon when the taxpayer had executed and filed, under § 272 (d), a waiver of the restrictions of § 272 (a) on the assessment …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"United Steelworkers of Am., AFL-CIOCLC v. Weber","cite":"443 U.S. 193","y":1979,"id":"1978/78-432","sc":1,"sum":"The Court held that the training scheme was legitimate because the 1964 Act \"did not intend to prohibit the private sector from taking effective steps\" to implement the goals of Title VII. Since the program sought to eliminate archaic patterns of racial segregation and hierarchy while not prohibiting white employees from advancing in the company, it was consistent with the intent of the law.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Washington v. Ill. Dep’t of Revenue","cite":"420 F.3d 658","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/420/658/","by":{"2":"24, 32","3":"12"}},{"t":"case","label":"Williams v. Bristol-Myers Squibb Co.","cite":"85 F.3d 270","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/85/270/","op":1,"ar":1,"by":{"2":"45"}},{"t":"usc","label":"42 U.S.C. § 3604","url":"https://www.law.cornell.edu/uscode/text/42/3604","subs":["(b)"],"by":{"2":"45"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","by":{"2":"45"}},{"t":"usc","label":"42 U.S.C. § 12182","url":"https://www.law.cornell.edu/uscode/text/42/12182","by":{"2":"45"}},{"t":"reg","label":"Update of Commission’s Conciliation Procedures, 86 Fed. Reg. 2974","url":"https://www.govinfo.gov/link/fr/86/2974","by":{"2":"47"}},{"t":"case","label":"Burchfield v. S. La. Med. Assocs.","cite":"2023 WL 5952183","y":2023,"court":"E.D. La. Sept. 13","by":{"3":"20"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"Dixon v. Plano Indep. Sch. Dist.","cite":"2023 WL 5434761","y":2023,"court":"E.D. Tex. Aug. 23","by":{"3":"20"}},{"t":"case","label":"Freier-Heckler v. McDonough","cite":"2022 WL 597472","y":2022,"court":"N.D. Ohio Feb. 28","by":{"3":"19"}},{"t":"case","label":"Hamilton v. Dallas Cnty.","cite":"79 F.4th 494","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/79/494/","by":{"3":"7, 20"}},{"t":"case","label":"Harris v. Mayorkas","cite":"2022 WL 3452316","y":2022,"court":"D.D.C. Aug. 18","by":{"3":"19"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Keith v. U.S. Gov’t Accountability Off.","cite":"2022 WL 3715776","y":2022,"court":"D.D.C. Aug. 29","op":1,"by":{"3":"19"}},{"t":"case","label":"Kessling v. Ohio State Univ.","cite":"2022 WL 17092250","y":2022,"court":"S.D. Ohio Nov. 21","by":{"3":"19"}},{"t":"case","label":"iv Leach v. Yellen","cite":"2023 WL 2496840","y":2023,"court":"D.D.C. Mar. 14","by":{"3":"20"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Rogers v. EEOC","cite":"454 F.2d 234","y":1971,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/454/234/","by":{"3":"9"}},{"t":"case","label":"Spring v. Sheboygan Area Sch. Dist.","cite":"865 F.2d 883","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/865/883/","by":{"3":"21, 22"}},{"t":"case","label":"St. Mary’s Honor Ctr. v. Hicks","cite":"509 U.S. 502","y":1993,"id":"1992/92-602","sc":1,"sum":"The trier of fact's rejection of an employer's asserted reasons for its actions does not entitle a plaintiff to judgment as a matter of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Vessels v. Atlanta Indep. Sch. Sys.","cite":"408 F.3d 763","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/408/763/","by":{"3":"18"}},{"t":"case","label":"v Wallace v. Performance Contractors, Inc.","cite":"57 F.4th 209","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/57/209/","by":{"3":"4"}},{"t":"case","label":"Watson v. Fort Worth Bank & Tr.","cite":"487 U.S. 977","y":1988,"id":"1987/86-6139","sc":1,"sum":"The judgment is vacated, and the case is remanded. 798 F. 2d 791, vacated and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, II-A, II-B, and III, concluding that disparate impact analysis may be applied to a subjective or discretionary promotion system. Pp. 985-991, 999-1000.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15, 16"}}]};